package com.cozyboats;

final class CatalogEntry
{
    static final int SOURCE_OBJECT = 0;
    static final int SOURCE_NPC = 1;

    final int sourceType;
    final int objectId;
    final int objectType;
    final int npcId;
    final int animationId;
    final String animationName;
    final String name;

    CatalogEntry(int objectId, int objectType, String name)
    {
        this(SOURCE_OBJECT, objectId, objectType, -1, -1, null, name);
    }

    static CatalogEntry animatedObject(int objectId, int objectType, int animationId, String name)
    {
        return new CatalogEntry(SOURCE_OBJECT, objectId, objectType, -1, animationId, "Loop", name);
    }

    static CatalogEntry animatedNpc(int npcId, int animationId, String animationName, String name)
    {
        return new CatalogEntry(SOURCE_NPC, -1, 10, npcId, animationId, animationName, name);
    }

    private CatalogEntry(int sourceType, int objectId, int objectType, int npcId,
        int animationId, String animationName, String name)
    {
        this.sourceType = sourceType;
        this.objectId = objectId;
        this.objectType = objectType;
        this.npcId = npcId;
        this.animationId = animationId;
        this.animationName = animationName;
        this.name = name;
    }

    boolean isNpc()
    {
        return sourceType == SOURCE_NPC;
    }

    boolean isAnimated()
    {
        return animationId >= 0;
    }

    int sourceId()
    {
        return isNpc() ? npcId : objectId;
    }

    String sourceLabel()
    {
        return isNpc() ? "NPC" : "Object";
    }

    String cacheKey()
    {
        return sourceType + ":" + sourceId() + ":" + objectType + ":" + animationId;
    }
}

package com.cozyboats;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import net.runelite.api.Model;

final class ModelPreviewRenderer
{
    private ModelPreviewRenderer()
    {
    }

    static BufferedImage render(Model model, int width, int height)
    {
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        graphics.setColor(new Color(24, 24, 27, 255));
        graphics.fillRoundRect(0, 0, width, height, 10, 10);

        float[] vx = model.getVerticesX();
        float[] vy = model.getVerticesY();
        float[] vz = model.getVerticesZ();
        int vertexCount = model.getVerticesCount();
        if (vertexCount == 0)
        {
            graphics.dispose();
            return image;
        }

        double minX = Double.MAX_VALUE, maxX = -Double.MAX_VALUE;
        double minY = Double.MAX_VALUE, maxY = -Double.MAX_VALUE;
        double[] tx = new double[vertexCount];
        double[] ty = new double[vertexCount];
        double[] tz = new double[vertexCount];
        double yaw = Math.toRadians(35);
        double pitch = Math.toRadians(22);
        for (int i = 0; i < vertexCount; i++)
        {
            double x = vx[i];
            double y = -vy[i];
            double z = vz[i];
            double rx = x * Math.cos(yaw) + z * Math.sin(yaw);
            double rz = -x * Math.sin(yaw) + z * Math.cos(yaw);
            double ry = y * Math.cos(pitch) - rz * Math.sin(pitch);
            rz = y * Math.sin(pitch) + rz * Math.cos(pitch);
            tx[i] = rx;
            ty[i] = ry;
            tz[i] = rz;
            minX = Math.min(minX, rx);
            maxX = Math.max(maxX, rx);
            minY = Math.min(minY, ry);
            maxY = Math.max(maxY, ry);
        }

        double spanX = Math.max(1, maxX - minX);
        double spanY = Math.max(1, maxY - minY);
        double scale = Math.min((width - 12) / spanX, (height - 12) / spanY);
        double centerX = (minX + maxX) / 2;
        double centerY = (minY + maxY) / 2;

        int[] faceA = model.getFaceIndices1();
        int[] faceB = model.getFaceIndices2();
        int[] faceC = model.getFaceIndices3();
        int[] colors = model.getFaceColors1();
        byte[] transparencies = model.getFaceTransparencies();
        List<Face> faces = new ArrayList<>(model.getFaceCount());
        for (int i = 0; i < model.getFaceCount(); i++)
        {
            int a = faceA[i], b = faceB[i], c = faceC[i];
            if (a >= vertexCount || b >= vertexCount || c >= vertexCount || colors[i] == -2)
            {
                continue;
            }
            faces.add(new Face(i, (tz[a] + tz[b] + tz[c]) / 3));
        }
        faces.sort(Comparator.comparingDouble(face -> face.depth));

        for (Face face : faces)
        {
            int i = face.index;
            int a = faceA[i], b = faceB[i], c = faceC[i];
            Polygon triangle = new Polygon(
                new int[]{project(tx[a], centerX, scale, width), project(tx[b], centerX, scale, width), project(tx[c], centerX, scale, width)},
                new int[]{projectY(ty[a], centerY, scale, height), projectY(ty[b], centerY, scale, height), projectY(ty[c], centerY, scale, height)},
                3);
            Color color = hslToColor(colors[i] < 0 ? 0 : colors[i]);
            int alpha = transparencies == null ? 255 : 255 - (transparencies[i] & 0xFF);
            graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha));
            graphics.fillPolygon(triangle);
        }
        graphics.dispose();
        return image;
    }

    private static int project(double value, double center, double scale, int size)
    {
        return (int) Math.round(size / 2.0 + (value - center) * scale);
    }

    private static int projectY(double value, double center, double scale, int size)
    {
        return (int) Math.round(size / 2.0 - (value - center) * scale);
    }

    private static Color hslToColor(int packed)
    {
        double h = ((packed >> 10) & 63) / 64.0;
        double s = ((packed >> 7) & 7) / 8.0;
        double l = (packed & 127) / 128.0;
        double q = l < .5 ? l * (1 + s) : l + s - l * s;
        double p = 2 * l - q;
        return new Color((float) hue(p, q, h + 1.0 / 3), (float) hue(p, q, h), (float) hue(p, q, h - 1.0 / 3));
    }

    private static double hue(double p, double q, double t)
    {
        if (t < 0) t++;
        if (t > 1) t--;
        if (t < 1.0 / 6) return p + (q - p) * 6 * t;
        if (t < 1.0 / 2) return q;
        if (t < 2.0 / 3) return p + (q - p) * (2.0 / 3 - t) * 6;
        return p;
    }

    private static final class Face
    {
        private final int index;
        private final double depth;

        private Face(int index, double depth)
        {
            this.index = index;
            this.depth = depth;
        }
    }
}

package com.cozyboats;

import net.runelite.api.Model;

final class ModelSafetyValidator
{
    private static final int MAX_VERTICES = 20_000;
    private static final int MAX_FACES = 40_000;
    private static final float MAX_COORDINATE = 131_072f;

    private ModelSafetyValidator()
    {
    }

    static boolean isSafe(Model model)
    {
        if (model == null)
        {
            return false;
        }
        int vertices = model.getVerticesCount();
        int faces = model.getFaceCount();
        if (vertices <= 0 || vertices > MAX_VERTICES || faces <= 0 || faces > MAX_FACES)
        {
            return false;
        }

        float[] x = model.getVerticesX();
        float[] y = model.getVerticesY();
        float[] z = model.getVerticesZ();
        int[] a = model.getFaceIndices1();
        int[] b = model.getFaceIndices2();
        int[] c = model.getFaceIndices3();
        int[] color1 = model.getFaceColors1();
        int[] color2 = model.getFaceColors2();
        int[] color3 = model.getFaceColors3();
        if (!hasLength(x, vertices) || !hasLength(y, vertices) || !hasLength(z, vertices)
            || !hasLength(a, faces) || !hasLength(b, faces) || !hasLength(c, faces)
            || !hasLength(color1, faces) || !hasLength(color2, faces) || !hasLength(color3, faces))
        {
            return false;
        }

        for (int i = 0; i < vertices; i++)
        {
            if (!Float.isFinite(x[i]) || !Float.isFinite(y[i]) || !Float.isFinite(z[i])
                || Math.abs(x[i]) > MAX_COORDINATE || Math.abs(y[i]) > MAX_COORDINATE || Math.abs(z[i]) > MAX_COORDINATE)
            {
                return false;
            }
        }
        for (int i = 0; i < faces; i++)
        {
            if (!validIndex(a[i], vertices) || !validIndex(b[i], vertices) || !validIndex(c[i], vertices))
            {
                return false;
            }
        }

        byte[] transparency = model.getFaceTransparencies();
        short[] textures = model.getFaceTextures();
        if ((transparency != null && transparency.length < faces) || (textures != null && textures.length < faces))
        {
            return false;
        }

        byte[] textureFaces = model.getTextureFaces();
        if (textureFaces != null)
        {
            if (textureFaces.length < faces)
            {
                return false;
            }
            int[] textureA = model.getTexIndices1();
            int[] textureB = model.getTexIndices2();
            int[] textureC = model.getTexIndices3();
            for (int i = 0; i < faces; i++)
            {
                int textureFace = textureFaces[i];
                if (textureFace == -1)
                {
                    continue;
                }
                int index = textureFace & 0xFF;
                if (!hasIndex(textureA, index) || !hasIndex(textureB, index) || !hasIndex(textureC, index)
                    || !validIndex(textureA[index], vertices) || !validIndex(textureB[index], vertices)
                    || !validIndex(textureC[index], vertices))
                {
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean hasLength(float[] values, int length)
    {
        return values != null && values.length >= length;
    }

    private static boolean hasLength(int[] values, int length)
    {
        return values != null && values.length >= length;
    }

    private static boolean hasIndex(int[] values, int index)
    {
        return values != null && index >= 0 && index < values.length;
    }

    private static boolean validIndex(int index, int size)
    {
        return index >= 0 && index < size;
    }
}

package com.cozyboats;

final class NpcDefinitionData
{
    String name;
    int[] modelIds;
    short[] recolorFrom;
    short[] recolorTo;
    short[] retextureFrom;
    short[] retextureTo;
    int standingAnimation = -1;
    int walkingAnimation = -1;
    int runAnimation = -1;
    int crawlAnimation = -1;
    int widthScale = 128;
    int heightScale = 128;
    int ambient;
    int contrast;
    boolean transforms;

    boolean isSafeForCustomRendering()
    {
        if (transforms || modelIds == null || modelIds.length == 0 || modelIds.length > 32)
        {
            return false;
        }
        for (int modelId : modelIds)
        {
            if (modelId < 0)
            {
                return false;
            }
        }
        return true;
    }
}

package com.cozyboats;

/**
 * Minimal NPC-definition decoder for models and the animations naturally
 * associated with them. Opcode lengths follow RuneLite's cache NpcLoader.
 */
final class NpcDefinitionDecoder
{
    private NpcDefinitionDecoder()
    {
    }

    static NpcDefinitionData decode(byte[] data)
    {
        NpcDefinitionData definition = new NpcDefinitionData();
        if (data == null)
        {
            return definition;
        }
        Reader in = new Reader(data);
        while (in.remaining() > 0)
        {
            int opcode = in.u8();
            if (opcode == 0)
            {
                break;
            }
            decodeOpcode(definition, in, opcode);
        }
        return definition;
    }

    private static void decodeOpcode(NpcDefinitionData d, Reader in, int opcode)
    {
        if (opcode == 1 || opcode == 60)
        {
            int count = in.u8();
            if (opcode == 1)
            {
                d.modelIds = new int[count];
                for (int i = 0; i < count; i++) d.modelIds[i] = in.u16();
            }
            else
            {
                in.skip(count * 2);
            }
        }
        else if (opcode == 2)
        {
            d.name = in.string();
        }
        else if (opcode == 12)
        {
            in.skip(1);
        }
        else if (opcode == 13)
        {
            d.standingAnimation = animation(in.u16());
        }
        else if (opcode == 14)
        {
            d.walkingAnimation = animation(in.u16());
        }
        else if (opcode == 15 || opcode == 16 || opcode == 18 || opcode == 95
            || opcode == 103 || opcode == 124 || opcode == 126 || (opcode >= 74 && opcode <= 79))
        {
            in.skip(2);
        }
        else if (opcode == 17)
        {
            d.walkingAnimation = animation(in.u16());
            in.skip(6);
        }
        else if (opcode >= 30 && opcode < 35)
        {
            in.string();
        }
        else if (opcode == 40 || opcode == 41)
        {
            int count = in.u8();
            short[] from = new short[count];
            short[] to = new short[count];
            for (int i = 0; i < count; i++)
            {
                from[i] = (short) in.u16();
                to[i] = (short) in.u16();
            }
            if (opcode == 40)
            {
                d.recolorFrom = from;
                d.recolorTo = to;
            }
            else
            {
                d.retextureFrom = from;
                d.retextureTo = to;
            }
        }
        else if (opcode == 61 || opcode == 62)
        {
            int count = in.u8();
            if (opcode == 61)
            {
                d.modelIds = new int[count];
                for (int i = 0; i < count; i++) d.modelIds[i] = in.i32();
            }
            else
            {
                in.skip(count * 4);
            }
        }
        else if (opcode == 93 || opcode == 99 || opcode == 107 || opcode == 109
            || opcode == 111 || opcode == 122 || opcode == 123 || opcode == 129
            || opcode == 130 || opcode == 145 || opcode == 147)
        {
            // Flag-only opcodes.
        }
        else if (opcode == 97)
        {
            d.widthScale = in.u16();
        }
        else if (opcode == 98)
        {
            d.heightScale = in.u16();
        }
        else if (opcode == 100)
        {
            d.ambient = in.i8();
        }
        else if (opcode == 101)
        {
            d.contrast = in.i8() * 5;
        }
        else if (opcode == 102)
        {
            int bitfield = in.u8();
            int count = 0;
            for (int bits = bitfield; bits != 0; bits >>>= 1) count++;
            for (int i = 0; i < count; i++)
            {
                if ((bitfield & (1 << i)) != 0)
                {
                    in.bigSmart2();
                    in.unsignedShortSmartMinusOne();
                }
            }
        }
        else if (opcode == 106 || opcode == 118)
        {
            d.transforms = true;
            in.skip(opcode == 118 ? 6 : 4);
            int count = in.u8();
            in.skip((count + 1) * 2);
        }
        else if (opcode == 114)
        {
            d.runAnimation = animation(in.u16());
        }
        else if (opcode == 115)
        {
            d.runAnimation = animation(in.u16());
            in.skip(6);
        }
        else if (opcode == 116)
        {
            d.crawlAnimation = animation(in.u16());
        }
        else if (opcode == 117)
        {
            d.crawlAnimation = animation(in.u16());
            in.skip(6);
        }
        else if (opcode == 146)
        {
            in.skip(2);
        }
        else if (opcode == 249)
        {
            int count = in.u8();
            for (int i = 0; i < count; i++)
            {
                boolean stringValue = in.u8() == 1;
                in.skip(3);
                if (stringValue) in.string(); else in.skip(4);
            }
        }
        else if (opcode == 251)
        {
            in.skip(2);
            in.string();
        }
        else if (opcode == 252)
        {
            in.skip(13);
            in.string();
        }
        else if (opcode == 253)
        {
            in.skip(14);
            in.string();
        }
        else
        {
            throw new IllegalArgumentException("Unknown NPC-definition opcode " + opcode);
        }
    }

    private static int animation(int id)
    {
        return id == 0xFFFF ? -1 : id;
    }

    private static final class Reader
    {
        private final byte[] data;
        private int offset;

        private Reader(byte[] data)
        {
            this.data = data;
        }

        int remaining()
        {
            return data.length - offset;
        }

        int u8()
        {
            require(1);
            return data[offset++] & 0xFF;
        }

        int i8()
        {
            return (byte) u8();
        }

        int u16()
        {
            return (u8() << 8) | u8();
        }

        int i32()
        {
            return (u8() << 24) | (u8() << 16) | (u8() << 8) | u8();
        }

        int bigSmart2()
        {
            require(1);
            return (data[offset] & 0x80) == 0 ? u16() : i32() & 0x7FFFFFFF;
        }

        int unsignedShortSmartMinusOne()
        {
            require(1);
            return (data[offset] & 0xFF) < 128 ? u8() - 1 : u16() - 32769;
        }

        String string()
        {
            StringBuilder value = new StringBuilder();
            int next;
            while ((next = u8()) != 0) value.append((char) next);
            return value.toString();
        }

        void skip(int amount)
        {
            require(amount);
            offset += amount;
        }

        void require(int amount)
        {
            if (amount < 0 || offset + amount > data.length)
            {
                throw new IllegalArgumentException("Truncated NPC definition");
            }
        }
    }
}

package com.cozyboats;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;

final class NpcModelFactory
{
    private static final int NPC_CONFIG_ARCHIVE = 9;
    private static final int CACHE_SIZE = 160;

    private final Client client;
    private final Map<Integer, Model> cache = Collections.synchronizedMap(
        new LinkedHashMap<Integer, Model>(CACHE_SIZE, .75f, true)
        {
            @Override
            protected boolean removeEldestEntry(Map.Entry<Integer, Model> eldest)
            {
                return size() > CACHE_SIZE;
            }
        });

    @Inject
    NpcModelFactory(Client client)
    {
        this.client = client;
    }

    Model create(PropPlacement placement)
    {
        Model base = createPreview(placement.npcId);
        if (base == null)
        {
            return null;
        }
        if (placement.scale == 128)
        {
            return ModelSafetyValidator.isSafe(base) ? base : null;
        }
        return createModel(placement.npcId, placement.scale);
    }

    Model createPreview(int npcId)
    {
        Model cached = cache.get(npcId);
        if (cached != null)
        {
            return cached;
        }
        Model model = createModel(npcId, 128);
        if (model != null)
        {
            cache.put(npcId, model);
        }
        return model;
    }

    private Model createModel(int npcId, int placementScale)
    {
        try
        {
            byte[] bytes = client.getIndexConfig().loadData(NPC_CONFIG_ARCHIVE, npcId);
            if (bytes == null)
            {
                return null;
            }
            NpcDefinitionData definition = NpcDefinitionDecoder.decode(bytes);
            if (!definition.isSafeForCustomRendering())
            {
                return null;
            }
            List<ModelData> parts = new ArrayList<>(definition.modelIds.length);
            for (int modelId : definition.modelIds)
            {
                ModelData part = client.loadModelData(modelId);
                if (part == null)
                {
                    return null;
                }
                part = part.shallowCopy().cloneVertices().cloneColors();
                if (part.getFaceTextures() != null) part = part.cloneTextures();
                if (part.getFaceTransparencies() != null) part = part.cloneTransparencies();
                parts.add(part);
            }
            ModelData data = parts.size() == 1 ? parts.get(0) : client.mergeModels(parts.toArray(new ModelData[0]));
            if (data == null)
            {
                return null;
            }
            if (definition.recolorFrom != null)
            {
                for (int i = 0; i < definition.recolorFrom.length; i++)
                {
                    data.recolor(definition.recolorFrom[i], definition.recolorTo[i]);
                }
            }
            if (definition.retextureFrom != null)
            {
                for (int i = 0; i < definition.retextureFrom.length; i++)
                {
                    data.retexture(definition.retextureFrom[i], definition.retextureTo[i]);
                }
            }
            if (definition.widthScale != 128 || definition.heightScale != 128)
            {
                data.scale(definition.widthScale, definition.heightScale, definition.widthScale);
            }
            if (placementScale != 128)
            {
                data.scale(placementScale, placementScale, placementScale);
            }
            Model model = data.light(64 + definition.ambient, 850 + definition.contrast, -30, -50, -30);
            if (ModelSafetyValidator.isSafe(model))
            {
                return model;
            }
        }
        catch (RuntimeException | AssertionError ignored)
        {
        }
        return null;
    }

    void clear()
    {
        cache.clear();
    }
}

package com.cozyboats;

final class ObjectDefinitionData
{
    String name;
    int[] modelIds;
    int[] modelTypes;
    boolean extendedModelIds;
    int animationId = -1;
    boolean transforms;
    short[] recolorFrom;
    short[] recolorTo;
    short[] retextureFrom;
    short[] retextureTo;
    boolean rotated;
    int scaleX = 128;
    int scaleHeight = 128;
    int scaleY = 128;
    int offsetX;
    int offsetHeight;
    int offsetY;
    int ambient;
    int contrast;

    boolean isSafeForCustomRendering()
    {
        // Extended model IDs are now the normal cache encoding even for old,
        // small IDs (for example Flower #1187 uses it for model 1610). The
        // encoding is not a safety signal; the decoded ID and resulting model
        // geometry are validated separately.
        if (transforms || modelIds == null || modelIds.length == 0 || modelIds.length > 8)
        {
            return false;
        }
        for (int modelId : modelIds)
        {
            if (modelId < 0)
            {
                return false;
            }
        }
        return true;
    }
}

package com.cozyboats;

/** Minimal object-definition decoder for the model-related cache opcodes. */
final class ObjectDefinitionDecoder
{
    private ObjectDefinitionDecoder()
    {
    }

    static ObjectDefinitionData decode(byte[] data)
    {
        ObjectDefinitionData definition = new ObjectDefinitionData();
        if (data == null)
        {
            return definition;
        }

        Reader in = new Reader(data);
        while (in.remaining() > 0)
        {
            int opcode = in.u8();
            if (opcode == 0)
            {
                break;
            }
            decodeOpcode(definition, in, opcode);
        }
        return definition;
    }

    private static void decodeOpcode(ObjectDefinitionData d, Reader in, int opcode)
    {
        switch (opcode)
        {
            case 1:
            {
                int count = in.u8();
                d.modelIds = new int[count];
                d.modelTypes = new int[count];
                for (int i = 0; i < count; i++)
                {
                    d.modelIds[i] = in.u16();
                    d.modelTypes[i] = in.u8();
                }
                return;
            }
            case 2:
                d.name = in.string();
                return;
            case 3:
            case 30:
            case 31:
            case 32:
            case 33:
            case 34:
                in.string();
                return;
            case 5:
            {
                int count = in.u8();
                d.modelIds = new int[count];
                d.modelTypes = null;
                for (int i = 0; i < count; i++)
                {
                    d.modelIds[i] = in.u16();
                }
                return;
            }
            case 6:
            {
                d.extendedModelIds = true;
                int count = in.u8();
                d.modelIds = new int[count];
                d.modelTypes = new int[count];
                for (int i = 0; i < count; i++)
                {
                    d.modelIds[i] = in.i32();
                    d.modelTypes[i] = in.u8();
                }
                return;
            }
            case 7:
            {
                d.extendedModelIds = true;
                int count = in.u8();
                d.modelIds = new int[count];
                d.modelTypes = null;
                for (int i = 0; i < count; i++)
                {
                    d.modelIds[i] = in.i32();
                }
                return;
            }
            case 14:
            case 15:
            case 19:
            case 28:
            case 69:
            case 75:
            case 81:
            case 104:
                in.skip(1);
                return;
            case 61:
            case 68:
            case 82:
            case 97:
            case 98:
            case 103:
                in.skip(2);
                return;
            case 24:
            {
                int animation = in.u16();
                d.animationId = animation == 0xFFFF ? -1 : animation;
                return;
            }
            case 29:
                d.ambient = in.i8();
                return;
            case 39:
                d.contrast = in.i8() * 25;
                return;
            case 40:
            {
                int count = in.u8();
                d.recolorFrom = new short[count];
                d.recolorTo = new short[count];
                for (int i = 0; i < count; i++)
                {
                    d.recolorFrom[i] = (short) in.u16();
                    d.recolorTo[i] = (short) in.u16();
                }
                return;
            }
            case 41:
            {
                int count = in.u8();
                d.retextureFrom = new short[count];
                d.retextureTo = new short[count];
                for (int i = 0; i < count; i++)
                {
                    d.retextureFrom[i] = (short) in.u16();
                    d.retextureTo[i] = (short) in.u16();
                }
                return;
            }
            case 62:
                d.rotated = true;
                return;
            case 65:
                d.scaleX = in.u16();
                return;
            case 66:
                d.scaleHeight = in.u16();
                return;
            case 67:
                d.scaleY = in.u16();
                return;
            case 70:
                d.offsetX = in.i16();
                return;
            case 71:
                d.offsetHeight = in.i16();
                return;
            case 72:
                d.offsetY = in.i16();
                return;
            case 77:
            case 92:
            {
                d.transforms = true;
                in.skip(4);
                if (opcode == 92)
                {
                    in.skip(2);
                }
                int count = in.u8();
                in.skip((count + 1) * 2);
                return;
            }
            case 78:
                in.skip(4);
                return;
            case 79:
            {
                in.skip(6);
                int count = in.u8();
                in.skip(count * 2);
                return;
            }
            case 90:
            case 94:
                return;
            case 91:
            case 95:
            case 96:
                in.skip(1);
                return;
            case 93:
                in.skip(6);
                return;
            case 100:
                in.skip(2);
                in.string();
                return;
            case 101:
                in.skip(13);
                in.string();
                return;
            case 102:
                in.skip(15);
                in.string();
                return;
            case 249:
            {
                int count = in.u8();
                for (int i = 0; i < count; i++)
                {
                    boolean stringValue = in.u8() == 1;
                    in.skip(3);
                    if (stringValue)
                    {
                        in.string();
                    }
                    else
                    {
                        in.skip(4);
                    }
                }
                return;
            }
            default:
                // Known flag-only opcodes.
                if ((opcode >= 17 && opcode <= 23) || opcode == 27 || opcode == 64
                    || opcode == 73 || opcode == 74 || opcode == 89 || opcode == 105)
                {
                    return;
                }
                throw new IllegalArgumentException("Unknown object-definition opcode " + opcode);
        }
    }

    private static final class Reader
    {
        private final byte[] data;
        private int offset;

        private Reader(byte[] data)
        {
            this.data = data;
        }

        int remaining()
        {
            return data.length - offset;
        }

        int u8()
        {
            require(1);
            return data[offset++] & 0xFF;
        }

        int i8()
        {
            return (byte) u8();
        }

        int u16()
        {
            return (u8() << 8) | u8();
        }

        int i16()
        {
            int value = u16();
            return value > 32767 ? value - 65536 : value;
        }

        int i32()
        {
            return (u8() << 24) | (u8() << 16) | (u8() << 8) | u8();
        }

        String string()
        {
            StringBuilder value = new StringBuilder();
            int next;
            while ((next = u8()) != 0)
            {
                value.append((char) next);
            }
            return value.toString();
        }

        void skip(int amount)
        {
            require(amount);
            offset += amount;
        }

        void require(int amount)
        {
            if (amount < 0 || offset + amount > data.length)
            {
                throw new IllegalArgumentException("Truncated object definition");
            }
        }
    }
}

package com.cozyboats;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

final class ObjectModelFactory
{
    private static final int OBJECT_CONFIG_ARCHIVE = 6;
    private static final int MODEL_CACHE_SIZE = 256;
    private static final Logger log = LoggerFactory.getLogger(ObjectModelFactory.class);

    private final Client client;
    private final Map<SourceKey, Model> capturedModels = boundedModelCache();
    private final Map<SourceKey, Model> generatedModels = boundedModelCache();
    private final Set<SourceKey> permanentlyFailed = new HashSet<>();

    @Inject
    ObjectModelFactory(Client client)
    {
        this.client = client;
    }

    void capture(int objectId, int type, int orientation, Model model)
    {
        if (model != null)
        {
            SourceKey key = new SourceKey(objectId, type, orientation);
            permanentlyFailed.remove(key);
            capturedModels.put(key, model);
        }
    }

    Model create(PropPlacement placement)
    {
        if (placement.objectId < 0 || placement.modelId >= 0)
        {
            return null;
        }

        SourceKey key = new SourceKey(placement.objectId, placement.objectType, placement.objectOrientation);
        Model base = capturedModels.get(key);
        if (base == null && permanentlyFailed.contains(key))
        {
            return null;
        }
        if (base == null)
        {
            base = generatedModels.get(key);
        }
        if (base == null)
        {
            base = createObjectModel(key);
        }

        if (base == null)
        {
            return null;
        }
        if (placement.scale == 128)
        {
            return ModelSafetyValidator.isSafe(base) ? base : reject(key);
        }
        return createObjectModel(key, placement.scale, false);
    }

    Model createPreview(int objectId, int type)
    {
        SourceKey key = new SourceKey(objectId, type, 0);
        if (permanentlyFailed.contains(key))
        {
            return null;
        }
        Model cached = generatedModels.get(key);
        return cached != null ? cached : createObjectModel(key);
    }

    void clear()
    {
        capturedModels.clear();
        generatedModels.clear();
        permanentlyFailed.clear();
    }

    boolean isPermanentlyFailed(PropPlacement placement)
    {
        return permanentlyFailed.contains(new SourceKey(placement.objectId, placement.objectType, placement.objectOrientation));
    }

    private Model reject(SourceKey key)
    {
        permanentlyFailed.add(key);
        generatedModels.remove(key);
        capturedModels.remove(key);
        return null;
    }

    private Model createObjectModel(SourceKey key)
    {
        return createObjectModel(key, 128, true);
    }

    private Model createObjectModel(SourceKey key, int placementScale, boolean cacheResult)
    {
        try
        {
            byte[] bytes = client.getIndexConfig().loadData(OBJECT_CONFIG_ARCHIVE, key.objectId);
            // Temporarily unavailable cache data is not a permanent model
            // failure and must never blacklist a known-good object.
            if (bytes == null)
            {
                return null;
            }
            ObjectDefinitionData definition = ObjectDefinitionDecoder.decode(bytes);
            if (!definition.isSafeForCustomRendering())
            {
                log.debug("Object {} decoded as unsupported: name={}, models={}, extended={}, animation={}, transforms={}",
                    key.objectId, definition.name,
                    definition.modelIds == null ? "null" : java.util.Arrays.toString(definition.modelIds),
                    definition.extendedModelIds, definition.animationId, definition.transforms);
                return reject(key);
            }

            List<ModelData> parts = new ArrayList<>();
            for (int i = 0; i < definition.modelIds.length; i++)
            {
                if (definition.modelTypes != null && definition.modelTypes[i] != key.type)
                {
                    continue;
                }
                if (definition.modelTypes == null && key.type != 10)
                {
                    continue;
                }

                ModelData part = client.loadModelData(definition.modelIds[i]);
                if (part == null)
                {
                    return null;
                }
                part = part.shallowCopy().cloneVertices().cloneColors();
                if (part.getFaceTextures() != null)
                {
                    part = part.cloneTextures();
                }
                if (part.getFaceTransparencies() != null)
                {
                    part = part.cloneTransparencies();
                }
                if (definition.rotated)
                {
                    part.rotateY180Ccw();
                }
                parts.add(part);
            }

            if (parts.isEmpty())
            {
                return null;
            }
            ModelData data = parts.size() == 1 ? parts.get(0) : client.mergeModels(parts.toArray(new ModelData[0]));
            if (data == null)
            {
                return null;
            }

            switch (key.orientation & 3)
            {
                case 1:
                    data.rotateY90Ccw();
                    break;
                case 2:
                    data.rotateY180Ccw();
                    break;
                case 3:
                    data.rotateY270Ccw();
                    break;
                default:
                    break;
            }

            if (definition.recolorFrom != null)
            {
                for (int i = 0; i < definition.recolorFrom.length; i++)
                {
                    data.recolor(definition.recolorFrom[i], definition.recolorTo[i]);
                }
            }
            if (definition.retextureFrom != null)
            {
                for (int i = 0; i < definition.retextureFrom.length; i++)
                {
                    data.retexture(definition.retextureFrom[i], definition.retextureTo[i]);
                }
            }
            if (definition.scaleX != 128 || definition.scaleHeight != 128 || definition.scaleY != 128)
            {
                data.scale(definition.scaleX, definition.scaleHeight, definition.scaleY);
            }
            if (definition.offsetX != 0 || definition.offsetHeight != 0 || definition.offsetY != 0)
            {
                data.translate(definition.offsetX, definition.offsetHeight, definition.offsetY);
            }
            if (placementScale != 128)
            {
                data.scale(placementScale, placementScale, placementScale);
            }
            Model model = data.light(64 + definition.ambient, 768 + definition.contrast, -50, -10, -50);
            if (model != null && ModelSafetyValidator.isSafe(model))
            {
                if (cacheResult)
                {
                    generatedModels.put(key, model);
                }
                return model;
            }
            return reject(key);
        }
        catch (RuntimeException ex)
        {
            permanentlyFailed.add(key);
            log.debug("Unable to decode or build object " + key.objectId, ex);
            return null;
        }
    }

    private static Map<SourceKey, Model> boundedModelCache()
    {
        return Collections.synchronizedMap(new LinkedHashMap<SourceKey, Model>(MODEL_CACHE_SIZE, .75f, true)
        {
            @Override
            protected boolean removeEldestEntry(Map.Entry<SourceKey, Model> eldest)
            {
                return size() > MODEL_CACHE_SIZE;
            }
        });
    }

    private static final class SourceKey
    {
        private final int objectId;
        private final int type;
        private final int orientation;

        private SourceKey(int objectId, int type, int orientation)
        {
            this.objectId = objectId;
            this.type = type;
            this.orientation = orientation;
        }

        @Override
        public boolean equals(Object other)
        {
            if (!(other instanceof SourceKey))
            {
                return false;
            }
            SourceKey key = (SourceKey) other;
            return objectId == key.objectId && type == key.type && orientation == key.orientation;
        }

        @Override
        public int hashCode()
        {
            return ((objectId * 31) + type) * 31 + orientation;
        }
    }
}

