    private final MouseAdapter placementMouseListener = new MouseAdapter()
    {
        @Override
        public MouseEvent mousePressed(MouseEvent event)
        {
            placementMouseClickConsumed = false;
            if (copied == null)
            {
                return event;
            }
            if (SwingUtilities.isRightMouseButton(event))
            {
                event.consume();
                placementMousePressConsumed = true;
                placementMouseClickConsumed = true;
                clientThread.invokeLater(() -> cancelPlacement("Placement cancelled."));
                return event;
            }
            if (SwingUtilities.isLeftMouseButton(event) && placementPreview != null
                && placementPreviewLocalPoint != null
                && placementPreviewTileLocalPoint != null
                && Perspective.getCanvasTilePoly(client, placementPreviewTileLocalPoint) != null
                && Perspective.getCanvasTilePoly(client, placementPreviewTileLocalPoint).contains(event.getPoint()))
            {
                LocalPoint point = placementPreviewTileLocalPoint;
                int plane = placementPreviewPlane;
                int offsetX = placementPreviewOffsetX;
                int offsetY = placementPreviewOffsetY;
                event.consume();
                placementMousePressConsumed = true;
                placementMouseClickConsumed = true;
                clientThread.invokeLater(() -> placeCopied(point, plane, offsetX, offsetY));
            }
            return event;
        }

        @Override
        public MouseEvent mouseReleased(MouseEvent event)
        {
            if (placementMousePressConsumed)
            {
                event.consume();
                placementMousePressConsumed = false;
            }
            return event;
        }

        @Override
        public MouseEvent mouseClicked(MouseEvent event)
        {
            if (placementMouseClickConsumed)
            {
                event.consume();
                placementMouseClickConsumed = false;
            }
            return event;
        }
    };

