    @Subscribe
    public void onGameTick(GameTick event)
    {
        updateBoatStatus();
        if (activeSafetyProbe != null)
        {
            if (++safetyProbeTicks >= SAFETY_PROBE_TICKS)
            {
                completeSafetyProbe();
            }
        }
        // Cache files and models can arrive asynchronously. Retry unresolved props occasionally.
        else if (++retryTick % 2 == 0 && rendered.size() < placements.size())
        {
            spawnUnrendered();
        }
        processCatalogueBatch();
    }

    @Subscribe
    public void onClientTick(ClientTick event)
    {
        if (copied == null || client.getGameState() != GameState.LOGGED_IN)
        {
            clearPlacementPreviewAndProbe();
            return;
        }

        WorldEntity boat = findOwnedBoat();
        WorldView worldView = boat == null ? null : boat.getWorldView();
        Tile tile = worldView == null ? null : worldView.getSelectedSceneTile();
        if (tile == null)
        {
            clearPlacementPreviewAndProbe();
            return;
        }
        updatePlacementPreview(worldView, tile.getLocalLocation());
    }

    private void updatePlacementPreview(WorldView worldView, LocalPoint localPoint)
    {
        PlacementTarget target = resolvePlacementTarget(worldView, localPoint);
        if (target == null)
        {
            clearPlacementPreview();
            return;
        }
        if (placementPreview != null && localPoint.equals(placementPreviewTileLocalPoint)
            && target.renderPoint.equals(placementPreviewLocalPoint))
        {
            return;
        }
        clearPlacementPreview();

        if (isBlocked(copied))
        {
            cancelPlacement("That object has been blocked by the safety system.");
            return;
        }
        if (!isTrusted(copied) && activeSafetyProbe != null
            && !sameSource(activeSafetyProbe, copied))
        {
            return;
        }

        Model model = createModel(copied);
        if (model == null)
        {
            return;
        }

        PropPlacement probe = copied.duplicateAt(localPoint.getX(), localPoint.getY(), worldView.getPlane());
        probe.offsetX = target.offsetX;
        probe.offsetY = target.offsetY;
        RuneLiteObject preview = client.createRuneLiteObject();
        preview.setModel(model);
        preview.setLocation(target.renderPoint, worldView.getPlane());
        preview.setOrientation(copied.rotation & 2047);
        preview.setZ(preview.getZ() - copied.height);
        preview.setRadius(Math.max(60, 60 * copied.scale / 128));
        if (!applyAnimation(preview, copied))
        {
            preview.setActive(false);
            return;
        }

        if (!isTrusted(copied) && activeSafetyProbe == null)
        {
            beginSafetyProbe(probe);
            placementPreviewOwnsSafetyProbe = true;
        }
        try
        {
            preview.setActive(true);
        }
        catch (RuntimeException | AssertionError ex)
        {
            preview.setActive(false);
            blockObject(probe);
            clearSafetyProbe(false);
            copied = null;
            log.warn("Blocked object {} after preview activation failure", probe.objectId, ex);
            return;
        }
        placementPreview = preview;
        placementPreviewLocalPoint = target.renderPoint;
        placementPreviewTileLocalPoint = localPoint;
        placementPreviewPlane = worldView.getPlane();
        placementPreviewOffsetX = target.offsetX;
        placementPreviewOffsetY = target.offsetY;
    }

    private PlacementTarget resolvePlacementTarget(WorldView worldView, LocalPoint tileCentre)
    {
        PlacementMode mode = getPlacementMode();
        if (!mode.followsCursor())
        {
            LocalPoint renderPoint = tileCentre.plus(copied.offsetX, copied.offsetY);
            return renderPoint.isInScene()
                ? new PlacementTarget(renderPoint, copied.offsetX, copied.offsetY) : null;
        }

        net.runelite.api.Point mouse = client.getMouseCanvasPosition();
        if (mouse == null || mouse.getX() < 0 || mouse.getY() < 0)
        {
            return new PlacementTarget(tileCentre, 0, 0);
        }

        int step = mode.getLocalStep();
        long bestDistance = Long.MAX_VALUE;
        PlacementTarget best = null;
        for (int offsetX = -MAX_NUDGE; offsetX <= MAX_NUDGE; offsetX += step)
        {
            for (int offsetY = -MAX_NUDGE; offsetY <= MAX_NUDGE; offsetY += step)
            {
                LocalPoint candidate = tileCentre.plus(offsetX, offsetY);
                if (!candidate.isInScene())
                {
                    continue;
                }
                net.runelite.api.Point canvasPoint =
                    Perspective.localToCanvas(client, candidate, worldView.getPlane());
                if (canvasPoint == null)
                {
                    continue;
                }
                long dx = canvasPoint.getX() - mouse.getX();
                long dy = canvasPoint.getY() - mouse.getY();
                long distance = dx * dx + dy * dy;
                if (distance < bestDistance)
                {
                    bestDistance = distance;
                    best = new PlacementTarget(candidate, offsetX, offsetY);
                }
            }
        }
        return best;
    }

    private void rotatePlacementPreview(PropPlacement selected, int wheelRotation)
    {
        if (copied != selected)
        {
            return;
        }

        selected.rotation = (selected.rotation + wheelRotation * PLACEMENT_ROTATION_STEP) & 2047;
        if (placementPreview != null)
        {
            placementPreview.setOrientation(selected.rotation);
        }
    }

    private void clearPlacementPreview()
    {
