        {
            placementPreview.setActive(false);
            placementPreview = null;
        }
        placementPreviewLocalPoint = null;
        placementPreviewTileLocalPoint = null;
        placementPreviewPlane = 0;
        placementPreviewOffsetX = 0;
        placementPreviewOffsetY = 0;
    }

