        g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.setColor(new Color(238, 214, 150));
        g.drawLine(15, 4, 15, 22);
        g.setColor(new Color(245, 188, 94));
        int[] sailX = {14, 14, 5};
        int[] sailY = {6, 19, 19};
        g.fillPolygon(sailX, sailY, 3);
        g.setColor(new Color(196, 120, 211));
        int[] smallSailX = {17, 17, 25};
