    @Test
    public void newPlacementPresetsUseValidModelValues()
    {
        Assert.assertTrue(java.lang.reflect.Modifier.isPublic(PlacementScale.class.getModifiers()));
        Assert.assertTrue(java.lang.reflect.Modifier.isPublic(PlacementHeight.class.getModifiers()));
        Assert.assertTrue(java.lang.reflect.Modifier.isPublic(PlacementRotation.class.getModifiers()));
        Assert.assertEquals(64, PlacementScale.HALF.getScale());
        Assert.assertEquals(128, PlacementScale.NORMAL.getScale());
        Assert.assertEquals(384, PlacementScale.TRIPLE.getScale());
        Assert.assertEquals(0, PlacementHeight.GROUND.getHeight());
        Assert.assertEquals(128, PlacementHeight.ONE_TILE.getHeight());
        Assert.assertEquals(0, PlacementRotation.DEGREES_0.getRotation());
        Assert.assertEquals(1792, PlacementRotation.DEGREES_315.getRotation());

        PropPlacement placement = new PropPlacement();
        placement.name = "Preset decoration";
        placement.objectId = 100;
        placement.boatLocalX = 3200;
        placement.boatLocalY = 3200;
        placement.scale = PlacementScale.TRIPLE.getScale();
        placement.height = PlacementHeight.ONE_TILE.getHeight();
        placement.rotation = PlacementRotation.DEGREES_315.getRotation();
        Assert.assertTrue(placement.isValid());
    }

    @Test
    public void boatCoordinatesAreCopiedAndValidated()
    {
        PropPlacement placement = new PropPlacement();
        placement.name = "Deck chair";
        placement.objectId = 100;
        placement.boatLocalX = 3200;
        placement.boatLocalY = 3201;
        placement.boatPlane = 0;
        Assert.assertTrue(placement.isValid());

        PropPlacement copied = placement.copy();
        Assert.assertEquals(3200, copied.boatLocalX);
        Assert.assertEquals(3201, copied.boatLocalY);
        Assert.assertEquals(0, copied.boatPlane);

        placement.boatPlane = 4;
        Assert.assertFalse(placement.isValid());
    }

    @Test
    public void nudgingKeepsTheBoatWorldViewAnchor()
    {
        LocalPoint deckPoint = new LocalPoint(3200, 3200, 42);
        LocalPoint nudged = deckPoint.plus(16, -8);

        Assert.assertEquals(3216, nudged.getX());
        Assert.assertEquals(3192, nudged.getY());
        Assert.assertEquals(42, nudged.getWorldView());
    }

